function getGoldenPath() {
  return [
    { type: 'pageApiCall', method: 'runVerifierStep', args: ["release-ch4"], afterMs: 350 },
    { type: 'pageApiCall', method: 'runVerifierStep', args: ["ignite-ch4"], afterMs: 500 },
    { type: 'wait', ms: 700, afterMs: 100 },
    { type: 'pageApiCall', method: 'runVerifierStep', args: ["finish-combustion"], afterMs: 300 },
  ];
}

function runVerifierStep(step) {
  const stepType = typeof step === 'string' ? step : step?.type;
  if (stepType === "release-ch4" || stepType === 'release-gas') {
    return releaseMethane('autoplay');
  }
  if (stepType === "ignite-ch4" || stepType === 'run-autoplay') {
    if (!state.gasReleased) {
      releaseMethane('autoplay');
    }
    return igniteMethane('autoplay');
  }
  if (stepType === "finish-combustion") {
    return finishReaction();
  }
  return false;
}

const { installCoursewareTestHarness } = globalThis.ChemSharedLib;

installCoursewareTestHarness({
  state,
  mapState() {
    const autoplayActive = guidedGasMotion.state.active || guidedIgnitionMotion.state.active;
    return {
      phase: autoplayActive ? 'autoplay' : reaction.state.phase,
      activeStep: state.activeStep,
      gasReleased: state.gasReleased,
      ignited: state.ignited,
      autoplayMotionActive: autoplayActive,
      reactionProgress: reaction.state.progress,
      recipe: state.recipe,
      source: state.source,
    };
  },
  getVerifierMeta() {
    return {
      supportsGoldenPath: true,
      successPhase: "result",
      failureStatusText: 'Thả chưa đúng vị trí',
    };
  },
  getCapabilities() {
    return recipeCapabilities;
  },
  getStepContract() {
    return recipeStepContract;
  },
  getGoldenPath,
  getDragPath(sampleId = 'methane_delivery_tube') {
    if (sampleId === 'alcohol_burner') {
      return {
        type: 'drag',
        from: projectWorldToCanvas(burner.anchors["flameOrigin"], camera, renderer),
        to: projectWorldToCanvas(testTube.anchors["steamOrigin"], camera, renderer),
        steps: 22,
        afterMs: 500,
      };
    }
    return {
      type: 'drag',
      from: projectWorldToCanvas(methaneSource.anchors["gripAnchor"], camera, renderer),
      to: projectWorldToCanvas(testTube.anchors["mouth"], camera, renderer),
      steps: 22,
      afterMs: 500,
    };
  },
  dragFromPageApi({ sampleId } = {}) {
    if (sampleId === 'alcohol_burner') {
      return igniteMethane('manual');
    }
    return releaseMethane('manual');
  },
  runVerifierStep,
});

autoplayButton?.addEventListener('click', () => {
  if (reaction.state.phase !== 'idle' || state.gasReleased || guidedGasMotion.state.active || guidedIgnitionMotion.state.active) {
    return;
  }
  guidedGasMotion.start();
});
